// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stderr output of the commands and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // Validate inputs
    if loadBalancerName == "" {
        return "", fmt.Errorf("loadBalancerName cannot be empty")
    }
    if outputFile == "" {
        return "", fmt.Errorf("outputFile cannot be empty")
    }

    // Create the aliyun command
    aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

    // Create the jq command
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    // Open output file for writing
    file, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer file.Close()

    // Pipe aliyun's stdout to jq's stdin
    aliyunStdout, err := aliyunCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
    }
    jqCmd.Stdin = aliyunStdout

    // Redirect jq's stdout to file
    jqCmd.Stdout = file

    // Capture stderr of both commands
    var aliyunStderr, jqStderr bytes.Buffer
    aliyunCmd.Stderr = &aliyunStderr
    jqCmd.Stderr = &jqStderr

    // Start jq first (so it's ready to read from stdin)
    if err := jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }

    // Start aliyun
    if err := aliyunCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Wait for aliyun to finish and close its stdout pipe to signal EOF to jq
    aliyunErr := aliyunCmd.Wait()
    aliyunStdout.Close()

    // Wait for jq to finish
    jqErr := jqCmd.Wait()

    // Combine stderr outputs
    var outputStr string
    if aliyunStderr.Len() > 0 {
        outputStr += "aliyun stderr:\n" + aliyunStderr.String()
    }
    if jqStderr.Len() > 0 {
        outputStr += "jq stderr:\n" + jqStderr.String()
    }

    // Check errors
    if aliyunErr != nil {
        return outputStr, fmt.Errorf("aliyun command failed: %w", aliyunErr)
    }
    if jqErr != nil {
        return outputStr, fmt.Errorf("jq command failed: %w", jqErr)
    }

    return outputStr, nil
}

