package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stderr output of the command pipeline and any error encountered.
//
// This implementation avoids shell injection by using the os/exec package
// directly and piping commands, instead of invoking a shell.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build commands
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe cmd1's stdout to cmd2's stdin
	pipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	cmd2.Stdin = pipe

	// Open output file for writing (command's stdout redirection)
	outFile, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	// Set cmd2's stdout to the file
	cmd2.Stdout = outFile

	// Capture stderr for both commands
	var stderrBuf bytes.Buffer
	cmd1.Stderr = &stderrBuf
	cmd2.Stderr = &stderrBuf

	// Start cmd2 first to consume output, then run cmd1
	if err := cmd2.Start(); err != nil {
		return stderrBuf.String(), fmt.Errorf("failed to start jq: %w", err)
	}
	errCmd1 := cmd1.Run()
	errCmd2 := cmd2.Wait()

	// Collect errors
	var runErr error
	if errCmd1 != nil {
		runErr = fmt.Errorf("aliyun command failed: %w", errCmd1)
	}
	if errCmd2 != nil {
		if runErr != nil {
			runErr = fmt.Errorf("%w; jq failed: %v", runErr, errCmd2)
		} else {
			runErr = fmt.Errorf("jq failed: %w", errCmd2)
		}
	}

	return stderrBuf.String(), runErr
}

