// QuerySLBAndExport runs the pipeline:
// aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > output.json
// and returns any stderr output along with the first error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
    cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    outFile, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer outFile.Close()

    var stderr1, stderr2 bytes.Buffer
    cmd1.Stderr = &stderr1
    cmd2.Stderr = &stderr2

    // Pipe cmd1 stdout -> cmd2 stdin
    pipe, err := cmd1.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create pipe: %w", err)
    }
    cmd2.Stdin = pipe
    cmd2.Stdout = outFile

    // Start cmd2 first (reader) then cmd1 (writer)
    if err := cmd2.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }
    if err := cmd1.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    cmd1Err := cmd1.Wait()
    pipe.Close()
    cmd2Err := cmd2.Wait()

    // Combine stderr for diagnostics
    var combined bytes.Buffer
    combined.Write(stderr1.Bytes())
    combined.Write(stderr2.Bytes())
    output := combined.String()

    if cmd1Err != nil {
        return output, fmt.Errorf("aliyun command error: %w", cmd1Err)
    }
    if cmd2Err != nil {
        return output, fmt.Errorf("jq command error: %w", cmd2Err)
    }
    return output, nil
}

