package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, writes it to the specified file,
// and returns the formatted JSON output along with any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName)

	// Build the jq command for formatting
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun stdout to jq stdin
	pipeReader, pipeWriter := io.Pipe()
	aliyunCmd.Stdout = pipeWriter
	jqCmd.Stdin = pipeReader

	// Capture jq's stdout and stderr
	var outputBuf bytes.Buffer
	var errBuf bytes.Buffer
	jqCmd.Stdout = &outputBuf
	jqCmd.Stderr = &errBuf

	// Start jq first so it's ready to read from the pipe
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("starting jq: %w", err)
	}

	// Start aliyun
	if err := aliyunCmd.Start(); err != nil {
		pipeWriter.Close()
		_ = jqCmd.Wait() // best-effort cleanup
		return "", fmt.Errorf("starting aliyun: %w", err)
	}

	// Wait for aliyun to finish, then close the pipe to signal EOF to jq
	aliyunErr := aliyunCmd.Wait()
	pipeWriter.Close()

	// Wait for jq to finish processing
	jqErr := jqCmd.Wait()

	// Handle errors from either command
	if aliyunErr != nil {
		return outputBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, errBuf.String())
	}
	if jqErr != nil {
		return outputBuf.String(), fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, errBuf.String())
	}

	outputStr := outputBuf.String()

	// Write the final output to the requested file
	if err := os.WriteFile(outputFile, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("writing output file: %w", err)
	}

	return outputStr, nil
}

