package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// It returns the standard error output of both commands and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	jqCmd.Stdin = aliyunStdout

	// Open the output file for jq's stdout
	outFile, err := os.Create(outputFile)
	if err != nil {
		aliyunStdout.Close()
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()
	jqCmd.Stdout = outFile

	// Capture stderr for both commands
	var stderrBuf bytes.Buffer
	aliyunCmd.Stderr = &stderrBuf
	jqCmd.Stderr = &stderrBuf

	// Start jq first so it's ready to accept input
	if err := jqCmd.Start(); err != nil {
		aliyunStdout.Close()
		return stderrBuf.String(), fmt.Errorf("failed to start jq: %w", err)
	}
	// jq now has its own copy of the read end, we can close ours
	aliyunStdout.Close()

	// Start the aliyun command
	if err := aliyunCmd.Start(); err != nil {
		// jq is already started; close its stdin by closing the pipe (already closed)
		// and wait for it to exit
		_ = jqCmd.Wait()
		return stderrBuf.String(), fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for jq to finish first; it will exit when it receives EOF from the pipe
	// (i.e., after aliyun exits and the write end is closed)
	jqErr := jqCmd.Wait()

	// Now wait for aliyun to clean up its resources
	aliyunErr := aliyunCmd.Wait()

	stderrOutput := stderrBuf.String()

	if aliyunErr != nil {
		return stderrOutput, fmt.Errorf("aliyun command failed: %w", aliyunErr)
	}
	if jqErr != nil {
		return stderrOutput, fmt.Errorf("jq command failed: %w", jqErr)
	}

	return stderrOutput, nil
}

