import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Create command for aliyun
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	// Create command for jq
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Set up pipe from aliyun stdout to jq stdin
	pipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	cmdJq.Stdin = pipe

	// Capture stdout and stderr of jq
	var jqStdout, jqStderr bytes.Buffer
	cmdJq.Stdout = &jqStdout
	cmdJq.Stderr = &jqStderr

	// Capture stderr of aliyun
	var aliyunStderr bytes.Buffer
	cmdAliyun.Stderr = &aliyunStderr

	// Start jq first to avoid deadlock (jq is ready to read)
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}
	// Start aliyun
	if err := cmdAliyun.Start(); err != nil {
		// Clean up jq if aliyun fails to start
		cmdJq.Wait()
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for aliyun to finish
	aliyunErr := cmdAliyun.Wait()
	// Close the write end of the pipe to signal EOF to jq
	pipe.Close()

	// Wait for jq to finish processing
	jqErr := cmdJq.Wait()

	// Check errors from both commands
	if aliyunErr != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, aliyunStderr.String())
	}
	if jqErr != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
	}

	// Write the jq output to the specified file
	if err := os.WriteFile(outputFile, jqStdout.Bytes(), 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return jqStdout.String(), nil
}

