// the formatted output as a string. Any error during command execution is returned.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate basic inputs
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// First command: aliyun slb DescribeLoadBalancers --LoadBalancerName <name>
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Second command: jq '.LoadBalancers.LoadBalancer[]'
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect stdout of cmd1 to stdin of cmd2
	pipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	cmd2.Stdin = pipe

	// Capture stdout of cmd2 (the formatted output)
	var outBuf bytes.Buffer
	cmd2.Stdout = &outBuf

	// Capture stderr of both commands to provide meaningful error messages
	var errBuf bytes.Buffer
	cmd1.Stderr = &errBuf
	cmd2.Stderr = &errBuf

	// Start the second command first
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run the first command; this will feed data into the pipe and then close it
	if err := cmd1.Run(); err != nil {
		// Wait for cmd2 to finish (it may also have an error due to broken pipe)
		_ = cmd2.Wait()
		return "", fmt.Errorf("aliyun command failed: %w\n%s", err, errBuf.String())
	}

	// Wait for jq to finish processing
	if err := cmd2.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w\n%s", err, errBuf.String())
	}

	// Write the captured output to the output file
	output := outBuf.String()
	if err := os.WriteFile(outputFile, []byte(output), 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return output, nil
}

func main() {
	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <LoadBalancerName> <OutputFile>\n", os.Args[0])
		os.Exit(1)
	}

	name := os.Args[1]
	outputFile := os.Args[2]

	result, err := QuerySLBAndExport(name, outputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Print("Operation successful. Output:\n", result)
}

