// It runs: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > outputFile
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
    cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    var stderr1, stderr2 bytes.Buffer
    cmd1.Stderr = &stderr1
    cmd2.Stderr = &stderr2

    pipe, err := cmd1.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create pipe: %w", err)
    }
    cmd2.Stdin = pipe

    f, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer f.Close()
    cmd2.Stdout = f

    // Start the reader (jq) first to avoid potential pipe blocking
    if err := cmd2.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }

    if err := cmd1.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    err1 := cmd1.Wait()
    err2 := cmd2.Wait()

    combinedStderr := stderr1.String() + stderr2.String()

    if err1 != nil {
        return combinedStderr, fmt.Errorf("aliyun command failed: %w", err1)
    }
    if err2 != nil {
        return combinedStderr, fmt.Errorf("jq command failed: %w", err2)
    }

    return combinedStderr, nil
}

func main() {
    if len(os.Args) < 3 {
        fmt.Fprintf(os.Stderr, "Usage: %s <LoadBalancerName> <outputFile>\n", os.Args[0])
        os.Exit(1)
