package main

import (
    "bytes"
    "fmt"
    "io"
    "os"
    "os/exec"
    "strings"
    "sync"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline (the jq output) and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // ali command
    aliCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
    aliStdout, err := aliCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create aliyun stdout pipe: %w", err)
    }

    aliStderr, err := aliCmd.StderrPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create aliyun stderr pipe: %w", err)
    }

    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
    jqCmd.Stdin = aliStdout

    var jqOutput bytes.Buffer
    jqCmd.Stdout = &jqOutput

    jqStderr, err := jqCmd.StderrPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create jq stderr pipe: %w", err)
    }

    // Start jq first (consumer)
    if err = jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }
    // Start aliyun (producer)
    if err = aliCmd.Start(); err != nil {
        // jq has been started; wait for it to avoid resource leak
        jqCmd.Wait()
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Read stderr from both concurrently to prevent deadlocks
    var aliStderrBuf, jqStderrBuf strings.Builder
    var wg sync.WaitGroup
    wg.Add(2)
    go func() {
        defer wg.Done()
        io.Copy(&aliStderrBuf, aliStderr)
    }()
    go func() {
        defer wg.Done()
        io.Copy(&jqStderrBuf, jqStderr)
    }()

    // Wait for commands to finish
    jqErr := jqCmd.Wait()
    aliErr := aliCmd.Wait()
    wg.Wait() // ensure all stderr copied

    combinedStderr := aliStderrBuf.String() + jqStderrBuf.String()

    // Write output to file
    err = os.WriteFile(outputFile, jqOutput.Bytes(), 0644)
    if err != nil {
        return "", fmt.Errorf("failed to write output file: %w", err)
    }

    if aliErr != nil || jqErr != nil {
        return jqOutput.String(), fmt.Errorf("pipeline error: aliyun: %v, jq: %v, stderr: %s", aliErr, jqErr, combinedStderr)
    }

    return jqOutput.String(), nil
}

