	}
	defer pipeReader.Close() // Close read end when we're done with it

	aliyunCmd.Stdout = pipeWriter
	jqCmd.Stdin = pipeReader

	// Capture stderr of both commands separately.
	var aliyunStderr, jqStderr bytes.Buffer
	aliyunCmd.Stderr = &aliyunStderr
	jqCmd.Stderr = &jqStderr

