package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Basic input validation: both parameters must be non‑empty.
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName must not be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile must not be empty")
	}

	// Build the two commands to avoid shell injection.
	// First command: aliyun slb DescribeLoadBalancers --LoadBalancerName <name>
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName)

	// Second command: jq '.LoadBalancers.LoadBalancer[]'
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe that connects aliyun's stdout to jq's stdin.
	pipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	cmdJq.Stdin = pipe

	// Capture stderr of both commands separately.
	var aliyunStderr bytes.Buffer
	var jqStderr bytes.Buffer
	cmdAliyun.Stderr = &aliyunStderr
	cmdJq.Stderr = &jqStderr

	// Capture the final output (stdout) from jq.
	var jqStdout bytes.Buffer
	cmdJq.Stdout = &jqStdout

	// Start jq first so it is ready to read from the pipe.
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Start aliyun.
	if err := cmdAliyun.Start(); err != nil {
		// If aliyun fails to start, we still need to clean up jq.
		_ = cmdJq.Wait()
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for aliyun to finish. After this, the pipe will be closed.
	aliyunErr := cmdAliyun.Wait()

	// Wait for jq to finish (it will stop once the pipe is closed).
	jqErr := cmdJq.Wait()

	// Combine any errors and captured stderr.
	if aliyunErr != nil || jqErr != nil || aliyunStderr.Len() > 0 || jqStderr.Len() > 0 {
		// Build a combined error message.
		errMsg := ""
		if aliyunStderr.Len() > 0 {
			errMsg += fmt.Sprintf("aliyun stderr: %s\n", aliyunStderr.String())
		}
		if jqStderr.Len() > 0 {
			errMsg += fmt.Sprintf("jq stderr: %s\n", jqStderr.String())
		}
		if aliyunErr != nil {
			errMsg += fmt.Sprintf("aliyun error: %v\n", aliyunErr)
		}
		if jqErr != nil {
			errMsg += fmt.Sprintf("jq error: %v\n", jqErr)
		}
		// Return the combined output (which may be partial jq stdout) and the errors.
		return jqStdout.String(), fmt.Errorf("command pipeline failed: %s", errMsg)
	}

	// Write the correctly formatted JSON to the output file.
	if err := os.WriteFile(outputFile, jqStdout.Bytes(), 0644); err != nil {
		return jqStdout.String(), fmt.Errorf("failed to write output file %q: %w", outputFile, err)
	}

	return jqStdout.String(), nil
}

