	cmdJq.Stdin = &aliyunStdout
	cmdJq.Stdout = &jqStdout
	cmdJq.Stderr = &jqStderr

	err = cmdJq.Run()
	if err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, jqStderr.String())
	}

	// Write the formatted output to the specified file
	err = os.WriteFile(outputFile, jqStdout.Bytes(), 0644)
	if err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	// Return the formatted result and no error
	return jqStdout.String(), nil
}

