package main

import (
    "bytes"
    "fmt"
    "os"
    "os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the JSON output and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    if loadBalancerName == "" || outputFile == "" {
        return "", fmt.Errorf("loadBalancerName and outputFile must not be empty")
    }

    aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    // Capture stderr for both commands to provide detailed errors
    var aliyunStderr bytes.Buffer
    aliyunCmd.Stderr = &aliyunStderr
    var jqStderr bytes.Buffer
    jqCmd.Stderr = &jqStderr

    // Pipe aliyun's stdout to jq's stdin
    pipe, err := aliyunCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe: %w", err)
    }
    jqCmd.Stdin = pipe

    // Capture jq's stdout (the final processed JSON)
    var jqStdout bytes.Buffer
    jqCmd.Stdout = &jqStdout

    // Start jq first so it is ready to read from the pipe
    if err := jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }
    // Start aliyun
    if err := aliyunCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Wait for aliyun to finish; this also closes the write end of the pipe
    aliyunErr := aliyunCmd.Wait()
    // Wait for jq to finish processing the pipe
    jqErr := jqCmd.Wait()

    if aliyunErr != nil {
        return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, aliyunStderr.String())
    }
    if jqErr != nil {
        return "", fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
    }

    output := jqStdout.String()

    // Write the result to the output file
    if err := os.WriteFile(outputFile, []byte(output), 0644); err != nil {
        return "", fmt.Errorf("failed to write output file: %w", err)
    }

    return output, nil
}

