	aliyunOutput, err := aliyunCmd.Output()
	if err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Run jq command with direct arguments, using aliyun output as stdin
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = nil // we'll use a pipe via StdinPipe or write to it
	stdinPipe, err := jqCmd.StdinPipe()
	if err != nil {
