import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, saves it to the specified file,
// and returns the formatted JSON along with any error encountered.
// It avoids shell injection by using direct command execution and piping.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// First command: aliyun slb DescribeLoadBalancers --LoadBalancerName <name>
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Second command: jq '.LoadBalancers.LoadBalancer[]'
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe between cmd1's stdout and cmd2's stdin
	pipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}
	cmd2.Stdin = pipe

	// Capture stdout from cmd2 and stderr from both commands
	var outBuf bytes.Buffer
	var errBuf1, errBuf2 bytes.Buffer

	cmd2.Stdout = &outBuf
	cmd1.Stderr = &errBuf1
	cmd2.Stderr = &errBuf2

	// Start cmd2 first so it is ready to receive input
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Run cmd1 (this closes the pipe when cmd1 finishes)
	if err := cmd1.Run(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, errBuf1.String())
	}

	// Wait for cmd2 to finish processing
	if err := cmd2.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, errBuf2.String())
	}

	// The formatted JSON is now in outBuf
	outputStr := outBuf.String()

	// Write the result to the desired output file
	if err := os.WriteFile(outputFile, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output file: %w", err)
	}

	return outputStr, nil
}

