package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the formatted output and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Basic validation: reject empty parameters
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("loadBalancerName and outputFile must not be empty")
	}

	// Create the output file (overwrite if exists)
	file, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer file.Close()

	// Buffer to capture the formatted output
	var stdoutBuf bytes.Buffer
	// MultiWriter writes to both the file and the buffer
	writer := io.MultiWriter(file, &stdoutBuf)

	// Create a pipe to connect aliyun's stdout to jq's stdin
	pr, pw := io.Pipe()

	// Prepare the commands with no shell, passing arguments directly
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Buffers for stderr of each command
	var stderrAliyun, stderrJq bytes.Buffer

	// Wire up aliyun
	cmdAliyun.Stdout = pw
	cmdAliyun.Stderr = &stderrAliyun

	// Wire up jq
	cmdJq.Stdin = pr
	cmdJq.Stdout = writer
	cmdJq.Stderr = &stderrJq

	// Start jq first so it is ready to read from the pipe
	if err := cmdJq.Start(); err != nil {
		pw.Close() // prevent pipe leak
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Start aliyun
	if err := cmdAliyun.Start(); err != nil {
		pw.Close()
		cmdJq.Wait() // allow jq to finish (will get EOF)
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for aliyun to finish, then close the pipe writer to signal EOF to jq
	aliyunErr := cmdAliyun.Wait()
	pw.Close()

	// Wait for jq to finish
	jqErr := cmdJq.Wait()

	// Build a combined error if any step failed
	var combinedErr error
	switch {
	case aliyunErr != nil && jqErr != nil:
		combinedErr = fmt.Errorf("aliyun error: %w, jq error: %w; aliyun stderr: %s, jq stderr: %s",
			aliyunErr, jqErr, stderrAliyun.String(), stderrJq.String())
	case aliyunErr != nil:
		combinedErr = fmt.Errorf("aliyun error: %w; stderr: %s", aliyunErr, stderrAliyun.String())
	case jqErr != nil:
		combinedErr = fmt.Errorf("jq error: %w; stderr: %s", jqErr, stderrJq.String())
	}

	// Return the captured stdout (formatted SLB data) and any errors
	return stdoutBuf.String(), combinedErr
}

