// QuerySLBAndExport runs the aliyun command to describe SLB load balancers,
// pipes the output to jq for filtering, and saves the result to the specified output file.
// It returns any stderr output combined from both commands and an error if something went wrong.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
    cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    // Connect cmd1's stdout to cmd2's stdin
    pipeReader, err := cmd1.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
    }
    cmd2.Stdin = pipeReader

    // Create the output file for cmd2's stdout
    file, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer file.Close()
    cmd2.Stdout = file

    // Capture stderr from both commands
    var stderr bytes.Buffer
    cmd1.Stderr = &stderr
    cmd2.Stderr = &stderr

    // Start cmd2 first so it is ready to receive input
    if err := cmd2.Start(); err != nil {
        return stderr.String(), fmt.Errorf("failed to start jq: %w", err)
    }
    if err := cmd1.Start(); err != nil {
        // cmd1 failed to start, terminate cmd2
        if cmd2.Process != nil {
            _ = cmd2.Process.Kill()
        }
        return stderr.String(), fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Wait for cmd1 to finish, then cmd2 will receive EOF and finish
    err1 := cmd1.Wait()
    err2 := cmd2.Wait()

    if err1 != nil {
        return stderr.String(), fmt.Errorf("aliyun command failed: %w", err1)
    }
    if err2 != nil {
        return stderr.String(), fmt.Errorf("jq command failed: %w", err2)
    }

    return stderr.String(), nil
}

