package main

import (
    "bytes"
    "fmt"
    "os"
    "os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the combined stderr of the pipeline and any error encountered.
// No shell is invoked, eliminating shell injection vulnerabilities.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // Create the output file
    outFile, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer outFile.Close()

    // jq command
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
    // aliyun command
    aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

    // Buffer to capture stderr from both commands
    var aliyunStderr, jqStderr bytes.Buffer
    aliyunCmd.Stderr = &aliyunStderr
    jqCmd.Stderr = &jqStderr

    // Pipe aliyun's stdout to jq's stdin
    pipe, err := aliyunCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create pipe: %w", err)
    }
    jqCmd.Stdin = pipe

    // Redirect jq's stdout to the output file
    jqCmd.Stdout = outFile

    // Start jq first so it's ready to read from the pipe
    if err := jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }
    if err := aliyunCmd.Start(); err != nil {
        // Clean up jq if aliyun fails to start
        jqCmd.Process.Kill()
        jqCmd.Wait()
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Wait for aliyun to complete, which closes the write end of the pipe
    aliyunErr := aliyunCmd.Wait()
    // Wait for jq to finish processing
    jqErr := jqCmd.Wait()

    // Combine stderr outputs to mimic original CombinedOutput behavior
    var combinedOutput bytes.Buffer
    combinedOutput.Write(aliyunStderr.Bytes())
    combinedOutput.Write(jqStderr.Bytes())
    outputStr := combinedOutput.String()

    if aliyunErr != nil {
        return outputStr, fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunErr, aliyunStderr.String())
    }
    if jqErr != nil {
        return outputStr, fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
    }

    return outputStr, nil
}

