// QuerySLBAndExport executes aliyun slb DescribeLoadBalancers,
// processes the output with jq, and saves the result to a file.
// It returns any stderr output from the commands and an error if something went wrong.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect aliyun stdout to jq stdin
	pipe, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	jqCmd.Stdin = pipe

	// Capture stderr from both commands
	var aliyunStderr, jqStderr bytes.Buffer
	aliyunCmd.Stderr = &aliyunStderr
	jqCmd.Stderr = &jqStderr

	// Capture jq stdout for writing to the output file
	var jqStdout bytes.Buffer
	jqCmd.Stdout = &jqStdout

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command (it reads from the pipe)
	if err := jqCmd.Start(); err != nil {
		_ = aliyunCmd.Wait() // avoid resource leak
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for jq to finish
	jqWaitErr := jqCmd.Wait()
	// Wait for aliyun to finish
	aliyunWaitErr := aliyunCmd.Wait()

	// Combine stderr for returning
	stderrOutput := aliyunStderr.String() + jqStderr.String()

	// Check errors from both commands
	if aliyunWaitErr != nil {
		return stderrOutput, fmt.Errorf("aliyun command failed: %w, stderr: %s", aliyunWaitErr, aliyunStderr.String())
	}
	if jqWaitErr != nil {
		return stderrOutput, fmt.Errorf("jq command failed: %w, stderr: %s", jqWaitErr, jqStderr.String())
	}

	// Write jq's standard output to the specified file
	if err := os.WriteFile(outputFile, jqStdout.Bytes(), 0644); err != nil {
		return stderrOutput, fmt.Errorf("failed to write output file: %w", err)
	}

	return stderrOutput, nil
}

