// QuerySLBAndExport runs aliyun slb DescribeLoadBalancers with the given loadBalancerName,
// pipes its JSON output through jq to extract the LoadBalancer array, and writes the result
// to outputFile. It returns the combined stderr of both commands and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// 1. aliyun command
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// 2. jq command
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect stdout of cmd1 to stdin of cmd2
	pipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd2.Stdin = pipe

	// Capture stderr separately for better diagnostics
	var stderr1, stderr2 bytes.Buffer
	cmd1.Stderr = &stderr1
	cmd2.Stderr = &stderr2

	// Open the output file and attach it to cmd2's stdout
	outFile, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()
	cmd2.Stdout = outFile

	// Start cmd2 first (so it is ready to consume the pipe)
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Start cmd1
	if err := cmd1.Start(); err != nil {
		// If cmd1 fails to start, kill cmd2 and clean up
		cmd2.Process.Kill()
		cmd2.Wait()
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for cmd1 to finish and then close the write end of the pipe
	var cmd1Err error
	done := make(chan struct{})
	go func() {
		cmd1Err = cmd1.Wait()
		pipe.Close()
		close(done)
	}()

	// Wait for cmd2 to finish (it will receive EOF when pipe is closed)
	cmd2Err := cmd2.Wait()
	<-done // ensure goroutine has finished (pipe closed)

	// Combine stderr messages
	var output string
	if stderr1.Len() > 0 {
		output = "aliyun stderr:\n" + stderr1.String()
	}
	if stderr2.Len() > 0 {
		if output != "" {
			output += "\n"
		}
		output += "jq stderr:\n" + stderr2.String()
	}

	// Return the first error encountered (if any)
	if cmd1Err != nil {
		return output, fmt.Errorf("aliyun command failed: %w", cmd1Err)
	}
	if cmd2Err != nil {
		return output, fmt.Errorf("jq command failed: %w", cmd2Err)
	}

	return output, nil
}

// main is provided for easy command‑line testing:
//   go run main.go <LoadBalancerName> <outputFile>
func main() {
	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <LoadBalancerName> <outputFile>\n", os.Args[0])
		os.Exit(1)
	}
	loadBalancerName := os.Args[1]
	outputFile := os.Args[2]

	output, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		if output != "" {
			fmt.Fprintf(os.Stderr, "Diagnostics:\n%s\n", output)
		}
		os.Exit(1)
	}
	if output != "" {
		fmt.Println(output)
	}
}

